using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Linq;
using System.Windows.Forms;
using CosineKitty;
namespace NightLens {
public class MapStar {public double Ra,Dec,Mag;public string Name;}
public class MapLabel {public double Ra,Dec;public string Name;}
public class SkyData {public List<MapStar> Stars=new List<MapStar>();public List<double[][]> Lines=new List<double[][]>();public List<MapLabel> Labels=new List<MapLabel>();}
static class StarCatalog {
 static SkyData data;public static string Error="";public static SkyData Data {get{if(data==null)try{data=Json.Read<SkyData>(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"StarCatalog","stars.json")));}catch(Exception e){Error=e.Message;data=new SkyData();}return data;}}
}
class SkyMap:Control {
 Pick pick;Night night;public double FieldDegrees{get;set;}=60;public double CenterRa{get;private set;}public double CenterDec{get;private set;}public Rectangle MapBounds{get;private set;}public int VisibleStars{get;private set;}public int VisibleSegments{get;private set;}
 public SkyMap(Pick p,Night n){pick=p;night=n;DoubleBuffered=true;Font=new Font("Segoe UI",9);Cursor=Cursors.Hand;if(p.Target.Body.HasValue){var eq=Astronomy.Equator(p.Target.Body.Value,new AstroTime(p.Best),n.Obs,EquatorEpoch.J2000,Aberration.Corrected);CenterRa=eq.ra*15;CenterDec=eq.dec;}else{CenterRa=p.Target.Ra*15;CenterDec=p.Target.Dec;}DoubleClick+=(a,b)=>ShowLarge();MouseWheel+=(a,b)=>{FieldDegrees=Math.Max(15,Math.Min(90,FieldDegrees*(b.Delta>0?.8:1.25)));Invalidate();};}
 public bool Project(double ra,double dec,out PointF point){double r=Math.PI/180,a=(ra-CenterRa)*r,d=dec*r,c=CenterDec*r;double divisor=Math.Sin(c)*Math.Sin(d)+Math.Cos(c)*Math.Cos(d)*Math.Cos(a);point=PointF.Empty;if(divisor<=0)return false;double x=-Math.Cos(d)*Math.Sin(a)/divisor,y=-(Math.Cos(c)*Math.Sin(d)-Math.Sin(c)*Math.Cos(d)*Math.Cos(a))/divisor;if(Math.Abs(x)>5||Math.Abs(y)>5)return false;double scale=MapBounds.Width/(2*Math.Tan(FieldDegrees*r/2));point=new PointF((float)(MapBounds.Left+MapBounds.Width/2.0+scale*x),(float)(MapBounds.Top+MapBounds.Height/2.0+scale*y));return true;}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Style.Card);int line=(int)Math.Ceiling(Font.GetHeight())+4;TextRenderer.DrawText(g,"SKY MAP · "+Astronomy.Constellation(CenterRa/15,CenterDec).Name,Font,new Rectangle(0,0,Width,line),Style.Text,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);MapBounds=new Rectangle(2,line+2,Math.Max(8,Width-4),Math.Max(8,Height-line*2-5));using(var brush=new SolidBrush(Style.Bg))g.FillRectangle(brush,MapBounds);var saved=g.Save();g.SetClip(MapBounds);VisibleStars=VisibleSegments=0;using(var pen=new Pen(Color.FromArgb(100,Style.Muted))){foreach(var chain in StarCatalog.Data.Lines)for(int i=1;i<chain.Length;i++){PointF a,b;if(Project(chain[i-1][0],chain[i-1][1],out a)&&Project(chain[i][0],chain[i][1],out b)){g.DrawLine(pen,a,b);if(MapBounds.Contains(Point.Round(a))||MapBounds.Contains(Point.Round(b)))VisibleSegments++;}}}
 var occupied=new List<Rectangle>();var center=new PointF(MapBounds.Left+MapBounds.Width/2f,MapBounds.Top+MapBounds.Height/2f);var targetLabel=new Rectangle((int)center.X-75,(int)center.Y+9,150,line);targetLabel.X=Math.Max(MapBounds.Left,Math.Min(MapBounds.Right-targetLabel.Width,targetLabel.X));occupied.Add(targetLabel);occupied.Add(new Rectangle((int)center.X-12,(int)center.Y-12,24,24));using(var brush=new SolidBrush(Style.Text)){foreach(var star in StarCatalog.Data.Stars.OrderBy(s=>s.Mag)){PointF p;if(!Project(star.Ra,star.Dec,out p)||!MapBounds.Contains(Point.Round(p)))continue;VisibleStars++;float radius=(float)Math.Max(.7,2.6-star.Mag*.3);g.FillEllipse(brush,p.X-radius,p.Y-radius,radius*2,radius*2);if(star.Mag<=3.5&&!string.IsNullOrWhiteSpace(star.Name)){var size=TextRenderer.MeasureText(star.Name,Font);var rect=new Rectangle((int)p.X+4,(int)p.Y-line/2,size.Width,line);if(MapBounds.Contains(rect)&&!occupied.Any(o=>o.IntersectsWith(rect))){TextRenderer.DrawText(g,star.Name,Font,rect,Style.Muted,TextFormatFlags.Left|TextFormatFlags.NoPadding);occupied.Add(rect);}}}}
 foreach(var label in StarCatalog.Data.Labels){PointF p;if(!Project(label.Ra,label.Dec,out p))continue;var size=TextRenderer.MeasureText(label.Name,Font);var rect=new Rectangle((int)p.X-size.Width/2,(int)p.Y-line/2,size.Width,line);if(MapBounds.Contains(rect)&&!occupied.Any(o=>o.IntersectsWith(rect))){TextRenderer.DrawText(g,label.Name,Font,rect,Style.Muted,TextFormatFlags.NoPadding);occupied.Add(rect);}}
 Color marker=Style.Theme=="Night"?Style.Text:Color.FromArgb(246,130,92);using(var pen=new Pen(marker,1.8f)){g.DrawEllipse(pen,center.X-6,center.Y-6,12,12);g.DrawLine(pen,center.X-11,center.Y,center.X-7,center.Y);g.DrawLine(pen,center.X+7,center.Y,center.X+11,center.Y);g.DrawLine(pen,center.X,center.Y-11,center.X,center.Y-7);g.DrawLine(pen,center.X,center.Y+7,center.X,center.Y+11);}using(var brush=new SolidBrush(Style.Bg))g.FillRectangle(brush,targetLabel);TextRenderer.DrawText(g,pick.Target.Body.HasValue?pick.Target.Body.Value.ToString():pick.Target.Canonical??pick.Target.Name,Font,targetLabel,marker,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);g.Restore(saved);TextRenderer.DrawText(g,"N ↑ · E ← · "+FieldDegrees.ToString("0")+"° · double-click to enlarge",Font,new Rectangle(0,Height-line,Width,line),Style.Muted,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}
 void ShowLarge(){using(var form=new Form()){Style.Form(form);form.Text="Sky map · "+pick.Target.Name;Style.FitScreen(form,1000,760);var root=Style.Grid(1,34,-100,35);root.Padding=new Padding(10);root.Controls.Add(Style.Label("Target centered · catalog stars and constellation lines · north up, east left",11,true),0,0);root.Controls.Add(new SkyMap(pick,night){Dock=DockStyle.Fill,FieldDegrees=FieldDegrees},0,1);root.Controls.Add(Style.Button("Close",(a,b)=>form.Close()),0,2);form.Controls.Add(root);form.ShowDialog(FindForm());}}
}
}
